DO $$ DECLARE v_actor uuid; v_lobby bigint; v_game uuid; v_saved jsonb; v_result jsonb; v_before numeric; v_after numeric; BEGIN SELECT user_id INTO v_actor FROM user_roles WHERE role='admin' LIMIT 1; IF v_actor IS NULL THEN RAISE EXCEPTION 'Rollback test needs an existing main admin'; END IF; BEGIN PERFORM set_config('request.jwt.claim.sub',v_actor::text,true); INSERT INTO active_async_matches(message_id,channel_id,guild_id,host_id,status,message_text,is_league,mode) VALUES('rollback-test','rollback-test','rollback-test','rollback-test','started','rollback-test',false,'live') RETURNING id INTO v_lobby; PERFORM sp_award('__rollback_test_a','match_start_base',50,now(),NULL,NULL,jsonb_build_object('match_id',v_lobby)); PERFORM sp_award('__rollback_test_a','match_start_base',50,now(),NULL,NULL,jsonb_build_object('match_id',v_lobby)); PERFORM sp_award('__rollback_test_a','first_live_game',100,now(),NULL,NULL,jsonb_build_object('match_id',v_lobby)); PERFORM sp_award('__rollback_test_a','first_weekly_async',350,now(),NULL,NULL,jsonb_build_object('match_id',v_lobby)); v_result:=admin_revert_match_and_sp(v_lobby,NULL,false,true,v_actor); IF (v_result->>'start_sp_reverted')::integer<>550 THEN RAISE EXCEPTION 'Start SP reversal failed'; END IF; IF EXISTS(SELECT 1 FROM sp_events WHERE metadata->>'match_id'=v_lobby::text) OR EXISTS(SELECT 1 FROM player_sp WHERE player_key='__rollback_test_a' AND lifetime_sp<>0) THEN RAISE EXCEPTION 'SP aggregates were not reversed'; END IF; v_result:=admin_revert_match_and_sp(v_lobby,NULL,false,true,v_actor); IF (v_result->>'start_sp_reverted')::integer<>0 THEN RAISE EXCEPTION 'Repeated reversal removed SP twice'; END IF; v_saved:=save_game_with_ratings('uprising',false,false,false,false,NULL,NULL,'[{"player_name":"__rollback_test_a","placement":1,"points":12},{"player_name":"__rollback_test_b","placement":2,"points":8}]'::jsonb); v_game:=(v_saved->>'game_id')::uuid; UPDATE games SET is_league=true WHERE id=v_game; UPDATE active_async_matches SET linked_game_id=v_game,status='started',is_league=true,season_num=987654 WHERE id=v_lobby; PERFORM apply_league_match_ratings(v_game,987654,'[{"player_key":"__rollback_test_a","elo_delta":12,"won":true},{"player_key":"__rollback_test_b","elo_delta":-12,"won":false}]'::jsonb); v_result:=admin_revert_match_and_sp(v_lobby,v_game,true,true,v_actor); IF EXISTS(SELECT 1 FROM games WHERE id=v_game) OR EXISTS(SELECT 1 FROM sp_events WHERE ref_game_id=v_game) OR EXISTS(SELECT 1 FROM league_match_rating_deltas WHERE game_id=v_game) THEN RAISE EXCEPTION 'Result data remains after rollback'; END IF; IF EXISTS(SELECT 1 FROM player_league_ratings WHERE season=987654 AND (elo<>1000 OR games_played<>0 OR wins<>0)) THEN RAISE EXCEPTION 'League Elo was not reverted exactly'; END IF; IF EXISTS(SELECT 1 FROM player_ratings WHERE player_key IN ('__rollback_test_a','__rollback_test_b') AND (elo<>1000 OR games_played<>0)) THEN RAISE EXCEPTION 'Global Elo was not reverted'; END IF; RAISE EXCEPTION USING ERRCODE='ZX001',MESSAGE='Rollback checks passed'; EXCEPTION WHEN SQLSTATE 'ZX001' THEN RAISE NOTICE 'All rollback tests passed; fixtures rolled back'; END; END $$;